/**
 * A navigation item displayed in the site's primary navigation.
 */
export interface NavItem {
  /**
   * The visible label for the navigation link.
   */
  label: string;
  /**
   * The URL or path the navigation item points to.
   */
  href: string;
}

/**
 * A call-to-action link used throughout the site.
 */
export interface CtaLink {
  /**
   * The visible text for the call-to-action.
   */
  label: string;
  /**
   * The URL or path the call-to-action points to.
   */
  href: string;
  /**
   * The visual style variant for the call-to-action.
   */
  variant: 'primary' | 'secondary';
}

/**
 * Content for the hero section of the site.
 */
export interface HeroContent {
  /**
   * A short introductory text shown above the main title.
   */
  eyebrow: string;
  /**
   * The main headline of the hero section.
   */
  title: string;
  /**
   * Supporting descriptive text under the main title.
   */
  subtitle: string;
  /**
   * The primary hero call-to-action.
   */
  primaryCta: CtaLink;
  /**
   * The secondary hero call-to-action.
   */
  secondaryCta: CtaLink;
}

/**
 * A highlighted stat or key point shown on the page.
 */
export interface Highlight {
  /**
   * Unique identifier for the highlight.
   */
  id: string;
  /**
   * Title of the highlight.
   */
  title: string;
  /**
   * Description providing detail for the highlight.
   */
  description: string;
  /**
   * Optional metric associated with the highlight.
   */
  metric?: string;
}

/**
 * A feature entry describing product capabilities.
 */
export interface Feature {
  /**
   * Unique identifier for the feature.
   */
  id: string;
  /**
   * Title of the feature.
   */
  title: string;
  /**
   * Description of the feature.
   */
  description: string;
  /**
   * Icon name or key representing the feature.
   */
  icon: string;
}

/**
 * A showcase item representing a highlighted example.
 */
export interface ShowcaseItem {
  /**
   * Unique identifier for the showcase item.
   */
  id: string;
  /**
   * Title of the showcase item.
   */
  title: string;
  /**
   * Description of the showcase item.
   */
  description: string;
  /**
   * Accessible alt text for the showcase image.
   */
  imageAlt: string;
  /**
   * Gradient token or CSS value used for visual styling.
   */
  gradient: string;
}

/**
 * A blog post preview item.
 */
export interface BlogPost {
  /**
   * Unique identifier for the blog post.
   */
  id: string;
  /**
   * Title of the blog post.
   */
  title: string;
  /**
   * Short excerpt summarizing the post.
   */
  excerpt: string;
  /**
   * Category label for the post.
   */
  category: string;
  /**
   * Published date as a display-ready string.
   */
  date: string;
  /**
   * Estimated reading time as a display-ready string.
   */
  readTime: string;
  /**
   * URL or path to the full blog post.
   */
  href: string;
}

/**
 * Complete structured content model for the site.
 */
export interface SiteContent {
  /**
   * Primary navigation items.
   */
  nav: NavItem[];
  /**
   * Hero section content.
   */
  hero: HeroContent;
  /**
   * Highlighted points or metrics.
   */
  highlights: Highlight[];
  /**
   * Product or service features.
   */
  features: Feature[];
  /**
   * Showcase entries.
   */
  showcase: ShowcaseItem[];
  /**
   * Recent or featured blog posts.
   */
  posts: BlogPost[];
  /**
   * Final call-to-action section content.
   */
  finalCta: {
    /**
     * Title for the final call-to-action section.
     */
    title: string;
    /**
     * Description for the final call-to-action section.
     */
    description: string;
    /**
     * Call-to-action link for the final section.
     */
    cta: CtaLink;
  };
}

