:root {
  --color-bg: #eef3fb;
  --color-bg-alt: #f8fbff;
  --color-surface: rgba(255, 255, 255, 0.62);
  --color-surface-strong: rgba(255, 255, 255, 0.82);
  --color-border: rgba(255, 255, 255, 0.58);
  --color-text: #0f172a;
  --color-text-muted: #4b5563;
  --color-primary: #2563eb;
  --color-primary-strong: #1d4ed8;
  --color-secondary: #0ea5e9;
  --color-shadow: rgba(15, 23, 42, 0.14);

  --gradient-page:
    radial-gradient(circle at 12% 10%, rgba(37, 99, 235, 0.16), transparent 46%),
    radial-gradient(circle at 86% 18%, rgba(14, 165, 233, 0.13), transparent 42%),
    linear-gradient(180deg, #fbfdff 0%, var(--color-bg) 52%, #e7eff9 100%);

  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 28px;

  --blur-sm: 14px;
  --blur-md: 22px;

  --shadow-sm: 0 10px 24px rgba(15, 23, 42, 0.09);
  --shadow-md: 0 20px 44px rgba(15, 23, 42, 0.12);

  --space-1: 0.5rem;
  --space-2: 0.75rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2rem;
  --space-6: 3rem;
  --space-7: 4rem;
  --space-8: 6rem;

  --container: 1120px;

  --transition-fast: 180ms ease;
  --transition-base: 280ms ease;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--color-text);
  background: var(--gradient-page);
  line-height: 1.55;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

.site-shell {
  width: min(calc(100% - 3rem), var(--container));
  margin: 0 auto;
  padding: var(--space-5) 0 var(--space-8);
}

.glass-nav {
  position: sticky;
  top: var(--space-3);
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
  padding: 0.9rem 1.15rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  backdrop-filter: blur(var(--blur-sm)) saturate(155%);
  -webkit-backdrop-filter: blur(var(--blur-sm)) saturate(155%);
  box-shadow: var(--shadow-sm);
}

.hero {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: var(--space-5);
  margin-bottom: var(--space-7);
}

.hero-card {
  padding: clamp(1.5rem, 2.4vw, 2.5rem);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: linear-gradient(145deg, var(--color-surface-strong), var(--color-surface));
  backdrop-filter: blur(var(--blur-md)) saturate(155%);
  -webkit-backdrop-filter: blur(var(--blur-md)) saturate(155%);
  box-shadow: var(--shadow-md);
}

.section {
  margin-bottom: var(--space-7);
}

.section-heading {
  margin: 0 0 var(--space-4);
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  line-height: 1.2;
  letter-spacing: -0.015em;
}

.highlight-grid,
.feature-grid,
.showcase-grid,
.blog-grid {
  display: grid;
  gap: var(--space-4);
}

.highlight-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.feature-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.showcase-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.blog-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.highlight-card,
.feature-card,
.showcase-card,
.blog-card,
.cta-panel {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  backdrop-filter: blur(var(--blur-sm)) saturate(145%);
  -webkit-backdrop-filter: blur(var(--blur-sm)) saturate(145%);
  box-shadow: var(--shadow-sm);
}

.highlight-card,
.feature-card,
.showcase-card,
.blog-card {
  padding: 1.2rem 1.15rem;
  transition: transform var(--transition-base), box-shadow var(--transition-base), border-color var(--transition-fast);
}

.highlight-card:hover,
.feature-card:hover,
.showcase-card:hover,
.blog-card:hover {
  transform: translateY(-3px);
  border-color: rgba(37, 99, 235, 0.28);
  box-shadow: var(--shadow-md);
}

.cta-panel {
  margin-top: var(--space-6);
  padding: clamp(1.25rem, 2vw, 2rem);
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.84), rgba(255, 255, 255, 0.58));
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.7rem 1.15rem;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast), border-color var(--transition-fast), color var(--transition-fast);
}

.button:hover {
  transform: translateY(-1px);
}

.button:active {
  transform: translateY(0);
}

.button.primary {
  color: #ffffff;
  background: linear-gradient(135deg, var(--color-primary), var(--color-primary-strong));
  box-shadow: 0 10px 20px rgba(37, 99, 235, 0.28);
}

.button.primary:hover {
  box-shadow: 0 14px 26px rgba(37, 99, 235, 0.35);
}

.button.secondary {
  color: var(--color-text);
  border-color: rgba(15, 23, 42, 0.12);
  background: rgba(255, 255, 255, 0.7);
}

.button.secondary:hover {
  border-color: rgba(15, 23, 42, 0.22);
  background: rgba(255, 255, 255, 0.9);
}

@media (max-width: 900px) {
  .site-shell {
    width: min(calc(100% - 2rem), var(--container));
    padding: var(--space-4) 0 var(--space-7);
  }

  .hero {
    grid-template-columns: 1fr;
    gap: var(--space-4);
  }

  .highlight-grid,
  .feature-grid,
  .blog-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .showcase-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .site-shell {
    width: min(calc(100% - 1.25rem), var(--container));
    padding: var(--space-3) 0 var(--space-6);
  }

  .glass-nav {
    position: static;
    margin-bottom: var(--space-5);
    flex-wrap: wrap;
    padding: 0.8rem 0.9rem;
  }

  .section {
    margin-bottom: var(--space-6);
  }

  .highlight-grid,
  .feature-grid,
  .showcase-grid,
  .blog-grid {
    grid-template-columns: 1fr;
    gap: var(--space-3);
  }

  .hero-card,
  .highlight-card,
  .feature-card,
  .showcase-card,
  .blog-card,
  .cta-panel {
    border-radius: var(--radius-sm);
  }

  .button {
    width: 100%;
  }
}

import React from 'react';
import type { CtaLink } from './types';

/**
 * Supported visual tone variants for the orb.
 */
type OrbTone = 'blue' | 'purple' | 'silver';

/**
 * Props for the section heading component.
 */
interface SectionHeadingProps {
  /**
   * Optional short text shown above the section title.
   */
  eyebrow?: string;
  /**
   * Primary heading text for the section.
   */
  title: string;
  /**
   * Optional supporting text displayed below the title.
   */
  description?: string;
}

/**
 * Props for the visual orb component.
 */
interface VisualOrbProps {
  /**
   * Accessible label describing the orb.
   */
  label: string;
  /**
   * Optional visual tone variant for the orb.
   */
  tone?: OrbTone;
}

/**
 * Joins class names while removing empty values.
 *
 * @param values - Potential class name values.
 * @returns A space-delimited class name string.
 */
function joinClasses(...values: Array<string | undefined>): string {
  return values
    .filter((value: string | undefined): value is string => typeof value === 'string' && value.trim().length > 0)
    .join(' ');
}

/**
 * Returns classes for the visual orb tone.
 *
 * @param tone - The selected orb tone.
 * @returns Utility classes for the given tone.
 */
function getToneClasses(tone: OrbTone): string {
  if (tone === 'purple') {
    return 'bg-gradient-to-br from-violet-300 via-purple-500 to-fuchsia-600';
  }

  if (tone === 'silver') {
    return 'bg-gradient-to-br from-slate-100 via-slate-300 to-slate-500';
  }

  return 'bg-gradient-to-br from-cyan-300 via-blue-500 to-indigo-600';
}

/**
 * Renders a call-to-action link styled as a button.
 *
 * @param props - Component props containing CTA data and optional class names.
 * @returns A styled anchor element.
 */
export function ButtonLink(props: { cta: CtaLink; className?: string }): React.JSX.Element {
  const { cta, className } = props;

  const baseClasses: string =
    'inline-flex items-center justify-center rounded-md px-4 py-2 text-sm font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2';
  const variantClasses: string =
    cta.variant === 'primary'
      ? 'bg-blue-600 text-white hover:bg-blue-500 focus-visible:ring-blue-600'
      : 'bg-transparent text-slate-900 ring-1 ring-inset ring-slate-300 hover:bg-slate-100 focus-visible:ring-slate-500';

  return (
    <a className={joinClasses(baseClasses, variantClasses, className)} href={cta.href}>
      {cta.label}
    </a>
  );
}

/**
 * Renders a reusable section heading block.
 *
 * @param props - Component props containing heading content.
 * @returns A semantic header with optional eyebrow and description.
 */
export function SectionHeading(props: SectionHeadingProps): React.JSX.Element {
  const { eyebrow, title, description } = props;
  const hasEyebrow: boolean = typeof eyebrow === 'string' && eyebrow.trim().length > 0;
  const hasDescription: boolean = typeof description === 'string' && description.trim().length > 0;

  return (
    <header className="space-y-3">
      {hasEyebrow ? <p className="text-sm font-semibold uppercase tracking-wide text-blue-600">{eyebrow}</p> : null}
      <h2 className="text-3xl font-bold tracking-tight text-slate-900 sm:text-4xl">{title}</h2>
      {hasDescription ? <p className="max-w-2xl text-base text-slate-600 sm:text-lg">{description}</p> : null}
    </header>
  );
}

/**
 * Renders a decorative orb with an accessible label.
 *
 * @param props - Component props containing label and optional tone.
 * @returns A styled visual element with screen-reader text.
 */
export function VisualOrb(props: VisualOrbProps): React.JSX.Element {
  const { label, tone = 'blue' } = props;

  return (
    <div className="relative inline-flex h-24 w-24 items-center justify-center" role="img" aria-label={label}>
      <span
        aria-hidden="true"
        className={joinClasses(
          'absolute inset-0 rounded-full opacity-80 blur-xl',
          getToneClasses(tone),
        )}
      />
      <span
        aria-hidden="true"
        className={joinClasses('relative block h-16 w-16 rounded-full shadow-lg', getToneClasses(tone))}
      />
    </div>
  );
}

import { createElement, type JSX } from 'react';
import type { NavItem } from './types';

/**
 * Renders the site's primary navigation from provided navigation items.
 */
export function Navigation(props: { items: NavItem[] }): JSX.Element {
  const safeItems: NavItem[] = Array.isArray(props.items)
    ? props.items.filter((item: NavItem): boolean => {
        const hasLabel: boolean = typeof item.label === 'string' && item.label.trim().length > 0;
        const hasHref: boolean = typeof item.href === 'string' && item.href.trim().length > 0;
        return hasLabel && hasHref;
      })
    : [];

  return createElement(
    'header',
    { className: 'site-nav' },
    createElement(
      'nav',
      {
        'aria-label': 'Primary',
      },
      createElement(
        'ul',
        {
          className: 'nav-links',
        },
        ...safeItems.map((item: NavItem, index: number): JSX.Element => {
          const label: string = item.label.trim();
          const href: string = item.href.trim();
          const key: string = `${href}-${label}-${index}`;

          return createElement(
            'li',
            { key },
            createElement(
              'a',
              {
                href,
              },
              label,
            ),
          );
        }),
      ),
    ),
  );
}

